; MAP-DATA BANK  —  bank 48 ($30):  compressed TILEMAPS + TILESETS (31 blocks)
; ############################################################################
; NOT code (old 'function table' = the LZ tile-block POINTER TABLE). Overworld/
; interior MAP data as LZ blocks (TileLoad $18A2). Block kinds (decoded):
;   TILESET  2048 B = 128 tiles -> VRAM $8000   (13 blocks)
;   TILEMAP   512 B = 32x16 tile numbers -> WRAM $C300  (18, those bank11 $4239 references)
;   GFX32     512 B = 32 tiles (graphics, not a map)   [512B blocks $4239 never maps]
; A room picks its {bank,block} via bank11 $4239. Compressed payload emitted as db
; (reassembles BYTE-EXACT); decompressed grids/tiles are commented reference below.
; Verify: rendertiles.py --detect flags this as TILE DATA.
; ############################################################################

